// Portfolio configuration
const portfolio = [
  { symbol: 'AAPL', shares: 50, costBasis: 150 },
  { symbol: 'MSFT', shares: 30, costBasis: 280 },
  { symbol: 'GOOGL', shares: 20, costBasis: 120 },
  { symbol: 'NVDA', shares: 25, costBasis: 450 },
  { symbol: 'AMZN', shares: 15, costBasis: 140 }
];

return portfolio.map(p => ({ json: p }));

const position = $('Get Portfolio').first().json;
const quote = $input.first().json;

const currentPrice = quote.c;
const marketValue = currentPrice * position.shares;
const costValue = position.costBasis * position.shares;
const gainLoss = marketValue - costValue;
const gainLossPercent = ((marketValue - costValue) / costValue * 100).toFixed(2);
const weeklyChange = ((currentPrice - quote.pc) / quote.pc * 100).toFixed(2);

return [{
  json: {
    symbol: position.symbol,
    shares: position.shares,
    costBasis: position.costBasis,
    currentPrice: currentPrice.toFixed(2),
    marketValue: marketValue.toFixed(2),
    gainLoss: gainLoss.toFixed(2),
    gainLossPercent,
    weeklyChange,
    isProfit: gainLoss > 0
  }
}];

const positions = $input.first().json.data;

let totalValue = 0;
let totalCost = 0;
let totalGainLoss = 0;

let report = `📊 *Weekly Portfolio Report*\n`;
report += `📅 ${new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}\n\n`;
report += `*Holdings:*\n\n`;

positions.forEach(p => {
  totalValue += parseFloat(p.marketValue);
  totalCost += p.costBasis * p.shares;
  totalGainLoss += parseFloat(p.gainLoss);

  const emoji = p.isProfit ? '🟢' : '🔴';
  const weekEmoji = parseFloat(p.weeklyChange) > 0 ? '↑' : '↓';

  report += `${emoji} *${p.symbol}*\n`;
  report += `   ${p.shares} shares @ $${p.currentPrice}\n`;
  report += `   Value: $${parseFloat(p.marketValue).toLocaleString()}\n`;
  report += `   P&L: $${parseFloat(p.gainLoss).toLocaleString()} (${p.gainLossPercent}%)\n`;
  report += `   Week: ${weekEmoji} ${p.weeklyChange}%\n\n`;
});

const totalGainLossPercent = ((totalValue - totalCost) / totalCost * 100).toFixed(2);
const profitEmoji = totalGainLoss > 0 ? '📈' : '📉';

report += `\n*Portfolio Summary:*\n`;
report += `💰 Total Value: $${totalValue.toLocaleString()}\n`;
report += `${profitEmoji} Total P&L: $${totalGainLoss.toLocaleString()} (${totalGainLossPercent}%)\n`;

return [{ json: { report, totalValue, totalGainLoss, totalGainLossPercent } }];
